#!/usr/bin/env python3
"""Pure-Python offline collector: the same PROTOCOL.md state machine as the C
library.  solver.py uses this only if compiling the C project is impossible;
behaviour and certificates are identical.  No I/O beyond CPU emulation."""
import hashlib
import struct
import zlib

from wire import NAMES, packet, payload as word_payload

MASK24 = 0x00FFFFFF
MASK32 = 0xFFFFFFFF
MASK64 = (1 << 64) - 1
FNV_OFFSET = 14695981039346656037
FNV_PRIME = 1099511628211


def _ipv4_checksum(header):
    total = 0
    for i in range(0, len(header) - 1, 2):
        total += (header[i] << 8) | header[i + 1]
    if len(header) % 2:
        total += header[-1] << 8
    while total >> 16:
        total = (total & 0xFFFF) + (total >> 16)
    return (~total) & 0xFFFF


def _icrc(frame):
    ip_len = (frame[16] << 8) | frame[17]
    crc = bytearray(b'\xff' * 8 + bytes(frame[14:len(frame) - 4]))
    crc[9] = 255
    crc[16] = 255
    crc[18] = 255
    crc[19] = 255
    crc[34] = 255
    crc[35] = 255
    crc[40] = 255
    return zlib.crc32(bytes(crc)) & MASK32


def wire_validate(frame, words):
    """Return (is_ack, psn, qpn, payload) or None when the frame is
    wire-invalid.  Rules are exactly those of PROTOCOL.md."""
    flen = len(frame)
    if flen < 14 + 20 + 8 + 12 + 4:
        return None
    if (frame[12] << 8) | frame[13] != 0x0800:
        return None
    if frame[14] != 0x45:
        return None
    ip_len = (frame[16] << 8) | frame[17]
    if ip_len < 44 or 14 + ip_len != flen:
        return None
    if frame[23] != 17:
        return None
    if ((frame[20] << 8) | frame[21]) not in (0x0000, 0x4000):
        return None
    hdr = bytearray(frame[14:34])
    hdr[10] = 0
    hdr[11] = 0
    if ((frame[24] << 8) | frame[25]) != _ipv4_checksum(hdr):
        return None
    udp_len = (frame[38] << 8) | frame[39]
    if udp_len != ip_len - 20:
        return None
    if (frame[34] << 8 | frame[35]) != 4791 or (frame[36] << 8 | frame[37]) != 4791:
        return None
    if (frame[40] << 8) | frame[41]:
        return None
    if udp_len < 24 + 4:
        return None
    opcode = frame[42]
    if opcode not in (0x04, 0x11):
        return None
    if frame[43] != 0:
        return None
    if (frame[44] << 8 | frame[45]) != 0xFFFF:
        return None
    qpn = (frame[46] << 24) | (frame[47] << 16) | (frame[48] << 8) | frame[49]
    if qpn >> 24:
        return None
    apsn = (frame[50] << 24) | (frame[51] << 16) | (frame[52] << 8) | frame[53]
    psn = apsn & MASK24
    if (apsn >> 24) != (0x80 if opcode == 0x04 else 0x00):
        return None
    body_len = udp_len - 24 - 4
    if opcode == 0x11:
        if body_len != 4:
            return None
        aeth = (frame[54] << 24) | (frame[55] << 16) | (frame[56] << 8) | frame[57]
        if (aeth >> 24) != 0x1F or (aeth & MASK24) != (psn + 1) & MASK24:
            return None
        payload = b''
    else:
        if body_len != 4 * words:
            return None
        payload = bytes(frame[54:54 + body_len])
    stored = (frame[flen - 1] << 24) | (frame[flen - 2] << 16) | \
             (frame[flen - 3] << 8) | frame[flen - 4]
    if stored != _icrc(frame):
        return None
    return (opcode == 0x11, psn, qpn & MASK24, payload)


def _ordinal_excluding(dst, src):
    return src - (1 if dst < src else 0)


def _rank_from_ordinal(dst, ordinal):
    n = 0
    for r in range(4):
        if r == dst:
            continue
        if n == ordinal:
            return r
        n += 1
    return 0


class Collector(object):
    def __init__(self, case):
        self.kind = case['primitive']
        self.mode = case['mode']
        self.root = case['root']
        self.K = case['segments']
        self.D = case['words']
        self.N = case['capacity']
        self.start = case['start'] & MASK24
        self.m = self.K // 4
        self.req_mask = (1 << self.root) if self.kind == 'broadcast' else 0xF
        self.outc = self._outc()
        self.b = 0
        self.slots = {}
        self.R = [0, 0, 0, 0]
        self.sent = [0, 0, 0, 0]
        self.down = [0, 0, 0, 0]
        self.up = [0, 0, 0, 0]
        self.repeat = [0, 0, 0, 0]
        self.c = [0] * 14
        self.budget = -1
        self.tape = hashlib.sha256()
        self.packets = 0
        self.nbytes = 0
        self.trace = []
        self.trace_limit = case.get('trace', 0)

    def _outc(self):
        K = self.K
        if self.kind in ('allreduce',):
            return [K] * 4
        if self.kind == 'reduce':
            return [K if d == self.root else 0 for d in range(4)]
        if self.kind == 'broadcast':
            return [0 if d == self.root else K for d in range(4)]
        if self.kind == 'barrier':
            return [1] * 4
        if self.kind == 'allgather':
            return [3 * K] * 4
        return [K // 4] * 4

    # ---------------- mapping ----------------
    def _rec_p(self, d, q):
        if self.kind == 'allgather':
            return q // 3
        if self.kind == 'reducescatter':
            return d * self.m + q
        if self.kind == 'barrier':
            return 0
        return q

    def _rec_src(self, d, q):
        if self.kind == 'allgather':
            return _rank_from_ordinal(d, q % 3)
        return -1

    def _complete(self, p):
        slot = self.slots.get(p)
        return slot is not None and slot[0] == self.req_mask

    # ---------------- egress ----------------
    def _transport(self, rank, frame):
        if self.budget == 0:
            return False
        if self.budget > 0:
            self.budget -= 1
        self.tape.update(bytes((rank,)) + struct.pack('<I', len(frame)) + frame)
        self.packets += 1
        self.nbytes += len(frame)
        if self.trace and len(self.trace) < self.trace_limit:
            self.trace.append({'rank': rank, 'hex': frame.hex()})
        return True

    def _send_ack(self, r, prefix):
        frame = packet(r, (self.start + prefix - 1) & MASK24, ack=True,
                       outgoing=True)
        if not self._transport(r, frame):
            self.c[11] += 1
            return False
        self.c[3] += 1
        return True

    def _result_frame(self, d, q):
        p = self._rec_p(d, q)
        slot = self.slots[p]
        kind = self.kind
        if kind == 'barrier':
            body = b''
        elif kind == 'broadcast':
            body = slot[1]
        elif kind == 'allgather':
            body = slot[2][self._rec_src(d, q)]
        else:
            body = struct.pack('!%dI' % self.D, *slot[1]) if self.D else b''
        return packet(d, (self.start + q) & MASK24, body, outgoing=True)

    def _eligible(self, r):
        R = self.R[r]
        if self.mode == 3:
            return R
        a = self.down
        kind = self.kind
        if kind in ('allreduce', 'barrier'):
            return min(R, a[r])
        if kind == 'reduce':
            return min(R, a[self.root])
        if kind == 'broadcast':
            if r != self.root:
                return 0
            return min([R] + [a[d] for d in range(4) if d != self.root])
        if kind == 'reducescatter':
            g = 0
            for d in range(4):
                t = min(self.m, a[d])
                g += t
                if t < self.m:
                    break
            return min(R, g)
        v = R
        for d in range(4):
            if d == r:
                continue
            o = _ordinal_excluding(d, r)
            n = a[d] - o + 2
            v = min(v, n // 3 if n > 0 else 0)
        return v

    def _retire(self):
        K = self.K
        kind = self.kind
        while self.b < K:
            p = self.b
            if not self._complete(p):
                break
            if kind == 'allgather':
                if min(self.down) < 3 * p + 3:
                    break
            elif kind == 'reducescatter':
                if self.down[p // self.m] < (p % self.m) + 1:
                    break
            elif kind == 'reduce':
                if self.down[self.root] < p + 1:
                    break
            elif kind == 'broadcast':
                if any(self.down[d] < p + 1 for d in range(4) if d != self.root):
                    break
            elif kind == 'barrier':
                if min(self.down) < 1:
                    break
            else:
                if min(self.down) < p + 1:
                    break
            srcs = [self.root] if kind == 'broadcast' else range(4)
            if any(self.up[r] <= p for r in srcs):
                break
            del self.slots[p]
            self.b = p + 1

    def _service(self, retry_rank=-1):
        stopped = False
        for r in range(4):
            e = self._eligible(r)
            if (e > self.up[r] or self.repeat[r]) and e > 0:
                if self._send_ack(r, e):
                    self.up[r] = e
                    self.repeat[r] = 0
                else:
                    stopped = True
                    break
        if not stopped and retry_rank >= 0:
            d = retry_rank
            for q in range(self.down[d], self.sent[d]):
                if self._transport(d, self._result_frame(d, q)):
                    self.c[2] += 1
                else:
                    self.c[11] += 1
                    stopped = True
                    break
        if not stopped:
            for d in range(4):
                while self.sent[d] < self.outc[d] and \
                        self._complete(self._rec_p(d, self.sent[d])):
                    if self._transport(d, self._result_frame(d, self.sent[d])):
                        self.c[2] += 1
                        self.sent[d] += 1
                    else:
                        self.c[11] += 1
                        stopped = True
                        break
                if stopped:
                    break
        self._retire()

    # ---------------- ingress ----------------
    def ingress(self, rank, frame):
        parsed = wire_validate(frame, self.D)
        if parsed is None:
            self.c[8] += 1
            return
        is_ack, psn, qpn, body = parsed
        if (frame[0:6] != bytes((2, 1, 0, 0, 0, rank + 1)) or
                frame[6:12] != bytes((2, 0, 0, 0, 0, rank + 1)) or
                frame[26:30] != bytes((10, 0, 0, rank + 1)) or
                frame[30:34] != bytes((10, 0, 0, 101 + rank)) or
                qpn != 0x200 + rank):
            self.c[9] += 1
            return
        if is_ack:
            self.c[1] += 1
            n = (psn - self.start + 1) & MASK24
            if n > self.down[rank] and n <= self.sent[rank]:
                self.down[rank] = n
            else:
                self.c[10] += 1
            self._service()
            return
        p = (psn - self.start) & MASK24
        if p >= self.K or (self.kind == 'broadcast' and rank != self.root):
            self.c[9] += 1
            return
        self.c[0] += 1
        b = self.b
        if p < b:
            self.c[7] += 1
            self.repeat[rank] = 1
            self._service()
            return
        window = min(self.K, b + self.N)
        if p >= window:
            self.c[6] += 1
            self._service()
            return
        slot = self.slots.get(p)
        bit = 1 << rank
        if slot is None:
            if self.kind in ('allreduce', 'reduce', 'reducescatter'):
                slot = [0, [0] * self.D, None]
            elif self.kind == 'allgather':
                slot = [0, None, [b''] * 4]
            else:
                slot = [0, b'', None]
            self.slots[p] = slot
        if slot[0] & bit:
            self.c[5] += 1
            self.repeat[rank] = 1
            self._service()
            return
        kind = self.kind
        if kind == 'broadcast':
            slot[1] = body
        elif kind == 'allgather':
            slot[2][rank] = body
        elif kind == 'barrier':
            pass
        else:
            words = struct.unpack('!%dI' % self.D, body) if self.D else ()
            if slot[0] == 0:
                slot[1] = list(words)
            else:
                slot[1] = [(x + y) & MASK32 for x, y in zip(slot[1], words)]
        slot[0] |= bit
        self.c[4] += 1
        while self.R[rank] < self.K:
            nxt = self.slots.get(self.R[rank])
            if nxt is None or not (nxt[0] & bit):
                break
            self.R[rank] += 1
        self._service()

    # ---------------- certificates ----------------
    def state(self):
        c = self.c
        return ([self.b, len(self.slots)] + self.R + self.sent + self.down +
                self.up + [c[0], c[1], c[2], c[3], c[4], c[5], c[6], c[7],
                           c[8], c[9], c[10], c[11], 0, 0])

    def digest(self):
        h = FNV_OFFSET
        fold = lambda value: ((h ^ value) * FNV_PRIME) & MASK64
        for p in sorted(self.slots):
            if p < self.b or p >= min(self.K, self.b + self.N):
                continue
            slot = self.slots[p]
            mask = slot[0]
            for byte in struct.pack('<Q', p) + bytes((mask,)) + \
                    bytes((1 if mask == self.req_mask else 0,)):
                h = ((h ^ byte) * FNV_PRIME) & MASK64
            if self.kind == 'allgather':
                for r in range(4):
                    present = 1 if (mask >> r) & 1 else 0
                    h = ((h ^ present) * FNV_PRIME) & MASK64
                    if present:
                        for byte in slot[2][r]:
                            h = ((h ^ byte) * FNV_PRIME) & MASK64
            elif self.kind == 'broadcast':
                for byte in slot[1]:
                    h = ((h ^ byte) * FNV_PRIME) & MASK64
            elif self.kind == 'barrier':
                pass
            else:
                for byte in struct.pack('<%dI' % self.D, *slot[1]):
                    h = ((h ^ byte) * FNV_PRIME) & MASK64
        return format(h, '016x')

    def certificate(self):
        return {'state': self.state(), 'buffer': self.digest(),
                'wire_sha256': self.tape.hexdigest(),
                'packets': self.packets, 'bytes': self.nbytes}

    def run(self, events):
        snaps = []
        self.trace = [] if self.trace_limit else []
        for name, arg, frame in events:
            if name == 'wire':
                self.ingress(arg, frame)
            elif name == 'flush':
                self._service()
            elif name == 'retry':
                self._service(arg)
            elif name == 'budget':
                self.budget = arg
            elif name == 'snap':
                snaps.append({'tag': arg, **self.certificate()})
            else:
                raise ValueError('unknown operation')
        out = self.certificate()
        out['snapshots'] = snaps
        out['trace'] = self.trace
        return out


def run_case(case):
    from wire import emissions
    return Collector(case).run(emissions(case))
